reference_solution:
def count_valid_clock_times(time):
    answer=0
    for hour in range(24):
        for minute in range(60):
            candidate=f'{hour:02d}:{minute:02d}'
            if all(given=='?' or given==actual for given,actual in zip(time,candidate)):answer+=1
    return answer

